#include "app.h"
#include "board_support.h"
#include "tool_hid.h"
#include "tool_radio.h"
#include "touchpad_filter.h"
#include "FatFs/ff.h"
#include <stdio.h>
#include <string.h>
const char app_display_name[]="STM32 Multi Tool";
static unsigned page,selected,total;static int focus=-1;static unsigned channels=84,previous_position,water_row,sweeps;static uint8_t previous_bars[126];static bool usb_ready,inside,release_click;static uint32_t refreshed;static RadioProfile rf;static ToolRadio family=RADIO_NRF24;static char names[8][13],script[8193],notice[80];static FATFS volume;
void board_background(void){if(usb_ready)tool_hid_task(tusb_time_millis_api());}
static void button(int x,int y,int w,const char*s){panel_button(x,y,w,s,0);}
static void scripts(void){total=0;if(f_mount(&volume,"0:",1)==FR_OK){DIR d;FILINFO f;if(f_opendir(&d,"0:/MULTI/MACROS")==FR_OK){while(total<8&&f_readdir(&d,&f)==FR_OK&&f.fname[0]){unsigned n=strlen(f.fname);if(!(f.fattrib&AM_DIR)&&n>4&&!strcmp(f.fname+n-4,".TXT")){snprintf(names[total++],13,"%s",f.fname);}}f_closedir(&d);}}f_mount(0,"0:",0);if(selected>=total)selected=0;}
static void load(void){tool_macro_cancel();delay_ms(30);if(!total){snprintf(notice,sizeof notice,"Copy TXT scripts to MULTI/MACROS");return;}char path[48];snprintf(path,sizeof path,"0:/MULTI/MACROS/%s",names[selected]);bool ok=false;if(f_mount(&volume,"0:",1)==FR_OK){FIL f;UINT n;if(f_open(&f,path,FA_READ)==FR_OK){if(f_size(&f)<=8192&&f_read(&f,script,8192,&n)==FR_OK){script[n]=0;ok=tool_macro_load(script,n);}f_close(&f);}}f_mount(0,"0:",0);snprintf(notice,sizeof notice,"%s",ok?"Loaded. ARM then press KEY1": "Load failed or script invalid");}
static void draw(void){board_status_line(0,0,0,0,0);rectangle(0,30,320,182,BLACK);if(!page){button(8,40,304,"RADIO SCANNER");button(8,82,304,"USB TOUCHPAD");button(8,124,304,"USB KEYBOARD MACROS");text(8,177,"Radio off until CONNECT",WHITE);return;}button(8,34,64,"BACK");if(page==1){button(80,34,112,family==RADIO_NRF24?"nRF24":"CC1101");button(200,34,112,"CONNECT");char label[40];if(family==RADIO_NRF24)snprintf(label,sizeof label,"2400-%u MHz | RPD",2399+channels);else snprintf(label,sizeof label,"CC %lu kHz | RSSI",(unsigned long)rf.frequency_khz);text(8,66,label,WHITE);memset(previous_bars,0,sizeof previous_bars);water_row=0;previous_position=0;focus=-1;button(8,176,96,"SCAN");button(112,176,96,"STOP");button(216,176,96,"BAND");}else if(page==2){text(88,40,"USB TOUCHPAD",CYAN);rectangle(8,70,304,68,0x18e4);text(32,96,"Slide stylus to move mouse",WHITE);button(8,144,32,"-");button(48,144,32,"+");char speed[16];snprintf(speed,sizeof speed,"%d.%02dx",pad_gain_value()/4,(pad_gain_value()%4)*25);text(88,152,speed,CYAN);const char*levels[]={"SMOOTH OFF","SMOOTH LOW","SMOOTH MED","SMOOTH HIGH"};button(160,144,152,levels[pad_smoothing_value()]);button(8,176,96,"LEFT");button(112,176,96,"RIGHT");button(216,176,96,"RELEASE");}else{button(80,34,64,"<");button(152,34,64,">");button(224,34,88,"SCAN");text(8,77,total?names[selected]:"No TXT scripts on SD",WHITE);button(8,105,96,"LOAD");button(112,105,96,"ARM");button(216,105,96,"CANCEL");text(8,146,"Press physical KEY1 to run",CYAN);text(8,173,"WK_UP cancels / returns home",WHITE);}}
void app_init(void){tool_radio_defaults(family,&rf);scripts();usb_ready=tool_hid_init();page=0;pad_reset();inside=false;release_click=false;notice[0]=0;draw();}
static void radio_display(void){
 unsigned count;const uint8_t*b=tool_radio_bins(&count);unsigned pos=tool_radio_scan_position();unsigned width=252/count;if(!width)width=1;
 if(tool_radio_scanning() && pos<previous_position){++sweeps;for(unsigned i=0;i<count;++i){unsigned v=b[i];unsigned color=v>40?RED:v>15?0xffe0:v>0?CYAN:0x0841;rectangle(8+i*width,112+water_row, width,1,color);}water_row=(water_row+1)%40;rectangle(8,112+water_row,252,1,WHITE);}
 previous_position=pos;
 for(unsigned i=0;i<count;++i){unsigned h=b[i]*20/100,old=previous_bars[i];if(h>old)rectangle(8+i*width,108-h,width,h-old,CYAN);else if(old>h)rectangle(8+i*width,108-old,width,old-h,BLACK);previous_bars[i]=h;}
 char line[60];unsigned hot=0;for(unsigned i=1;i<count;++i)if(b[i]>b[hot])hot=i;
 if(tool_radio_scanning()&&focus>=0&&(unsigned)focus<count)snprintf(line,sizeof line,"CH%u %uMHz %u%% | S%u",focus,2400+focus,b[focus],sweeps);else if(tool_radio_scanning())snprintf(line,sizeof line,"S%u CH%u HOT%u %u%%",sweeps,pos,hot,b[hot]);else snprintf(line,sizeof line,"%.38s",tool_radio_status());
 board_status_line(8,158,line,WHITE,BLACK);
}
void app_update(uint32_t now){tool_radio_tick(now);if(page==2&&!release_click){int dx,dy;if(pad_poll(now,tool_hid_connected(),&dx,&dy))pad_commit(tool_hid_mouse(dx,dy,0,0));}if(release_click&&tool_hid_mouse(0,0,0,0))release_click=false;if(now-refreshed<100)return;refreshed=now;if(page==1)radio_display();else if(page==3)board_status_line(8,188,notice[0]?notice:tool_macro_status(),WHITE,BLACK);else if(page==2)board_status_line(8,123,tool_hid_status(),WHITE,0x18e4);}
static void home(void){tool_macro_cancel();tool_hid_release();tool_radio_close();page=0;pad_reset();inside=false;draw();}
static void click(unsigned b){if(tool_hid_mouse(0,0,b,0))release_click=true;}
void app_touch(int x,int y,bool down){if(!down){inside=false;pad_stop();return;}if(page==2&&y>=70&&y<138){pad_point(x,y,tusb_time_millis_api());inside=true;return;}if(page==2)pad_stop();if(inside)return;inside=true;if(page&&y<63&&x<72){home();return;}if(!page){if(y>=40&&y<68)page=1;else if(y>=82&&y<110)page=2;else if(y>=124&&y<152)page=3;draw();return;}if(page==1){if(y>=85&&y<152&&family==RADIO_NRF24&&x>=8&&x<260){unsigned width=252/channels;focus=(x-8)/width;return;}if(y<63&&x<192){tool_radio_close();family=family==RADIO_NRF24?RADIO_CC1101:RADIO_NRF24;tool_radio_defaults(family,&rf);draw();}else if(y<63){tool_radio_open(&rf);if(family==RADIO_NRF24)tool_radio_set_channels(channels);draw();}else if(y>=176){if(x<104){if(!tool_radio_present())tool_radio_open(&rf);if(family==RADIO_NRF24)tool_radio_set_channels(channels);draw();tool_radio_scan_start();}else if(x<210)tool_radio_stop();else if(family==RADIO_NRF24){bool restart=tool_radio_scanning();channels=channels==84?126:84;tool_radio_set_channels(channels);draw();if(restart)tool_radio_scan_start();}else if(family==RADIO_CC1101){tool_radio_close();rf.frequency_khz=rf.frequency_khz==433920?868350:rf.frequency_khz==868350?915000:433920;snprintf(notice,sizeof notice,"CC %lu kHz",(unsigned long)rf.frequency_khz);draw();board_status_line(8,158,notice,WHITE,BLACK);}}}else if(page==2&&y>=144&&y<172){if(x<40)pad_gain(pad_gain_value()-1);else if(x<88)pad_gain(pad_gain_value()+1);else if(x>=160)pad_smoothing(pad_smoothing_value()+1);draw();}else if(page==2&&y>=176){if(x<104)click(1);else if(x<210)click(2);else tool_hid_release();}else if(page==3){if(y<63){tool_macro_cancel();notice[0]=0;if(x<144&&total)selected=(selected+total-1)%total;else if(x<216&&total)selected=(selected+1)%total;else scripts();draw();}else if(y>=105&&y<133){notice[0]=0;if(x<104)load();else if(x<210)tool_macro_arm();else tool_macro_cancel();}}}
void app_button(unsigned b){if(b&APP_BUTTON_WK_UP){home();return;}if(b&APP_BUTTON_KEY1){if(page==3&&tool_macro_armed()){notice[0]=0;tool_macro_run();}else if(page==2)click(1);}}
void app_shutdown(void){pad_reset();tool_radio_close();tool_hid_shutdown();usb_ready=false;f_mount(0,"0:",0);}
